"use client";

import { loadFont } from "@remotion/google-fonts/BricolageGrotesque";
import type React from "react";
import { AbsoluteFill, Easing, interpolate, spring } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_KEYS,
  DEFAULT_LABEL,
  type KeycapKey,
  type KeycapPressElementId,
  keycapPressTimeline,
  keyDefs,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["300", "400"],
  subsets: ["latin"],
});

export type { KeycapKey };

export interface KeycapPressProps {
  keys?: (string | KeycapKey)[];
  label?: string;
  material?: "dark" | "light";
  theme?: "dark" | "light";
  accent?: string;
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  /** Frames between words as the label writes in. */
  stagger?: number;
  /** Strength of the accent underglow beneath the keys, 0 to 1. */
  glow?: number;
  /** Text color of the label; overrides the theme ink. */
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the label and legends. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Size of the keys and label, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the keys, the presses, the chord, the camera
   * and the label's words, by the ids in `./timeline`.
   * Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<KeycapPressElementId>;
}

const LIGHT_GLASS: Partial<GradientParams> = {
  colors: ["#a9bbff", "#3b5bfd", "#1a2a9e", "#8fa6ff"],
};
const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const CAMERA = Easing.bezier(0.87, 0, 0.13, 1);
const HEAVY = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const MATERIALS = {
  dark: {
    top: [0x36, 0x36, 0x3c],
    sideTop: [0x2e, 0x2e, 0x34],
    sideBottom: [0x10, 0x10, 0x13],
    legend: "#ECEBE7",
    sub: "#8F8E95",
    rim: 0.3,
    dish: 0.34,
    sheen: 0.11,
    front: 0.4,
    left: 0.07,
    right: 0.45,
    shadow: "rgba(0,0,0,0.95)",
  },
  light: {
    top: [0xf7, 0xf6, 0xf2],
    sideTop: [0xe9, 0xe7, 0xe1],
    sideBottom: [0xa9, 0xa5, 0x9b],
    legend: "#2A2A2E",
    sub: "#8C8981",
    rim: 0.9,
    dish: 0.07,
    sheen: 0.5,
    front: 0.14,
    left: 0.35,
    right: 0.16,
    shadow: "rgba(58,48,32,0.5)",
  },
} as const;

const STAGES = {
  dark: {
    base: "#04050A",
    fg: "#F3F2EF",
    muted: "rgba(243,242,239,0.5)",
    ripple: "255,255,255",
    scrim: "4,5,10",
    scrimA: 0.42,
    glowA: 0.34,
    glowBlend: "screen",
  },
  light: {
    base: "#EEF0F6",
    fg: "#121214",
    muted: "rgba(18,18,20,0.5)",
    ripple: "96,88,74",
    scrim: "244,244,247",
    scrimA: 0.4,
    glowA: 0.16,
    glowBlend: "multiply",
  },
} as const;

const SYMBOLS: Record<string, string> = {
  "⌘": "M15 6v12a3 3 0 1 0 3-3H6a3 3 0 1 0 3 3V6a3 3 0 1 0-3 3h12a3 3 0 1 0-3-3",
  "⌥": "M3 5h6l6 14h6M14 5h7",
  "⇧": "M9 19v-6H5l7-8 7 8h-4v6z",
};

type Material = (typeof MATERIALS)[keyof typeof MATERIALS];

function rgb(c: readonly number[]) {
  return `rgb(${c[0]},${c[1]},${c[2]})`;
}

function mix(a: readonly number[], b: readonly number[], t: number) {
  return a.map((v, i) => Math.round(v + (b[i] - v) * t));
}

function hexToRgb(hex: string) {
  const h = hex.replace("#", "");
  const n = Number.parseInt(
    h.length === 3
      ? h
          .split("")
          .map((c) => c + c)
          .join("")
      : h,
    16,
  );
  return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
}

const SLICES = 18;

function profile(tt: number) {
  const fillet = Math.max(0, (tt - 0.72) / 0.28) ** 2;
  return tt * 0.68 + fillet * 0.32;
}

function Keycap({
  w,
  d,
  h,
  keyDef,
  m,
  unit,
  fontFamily,
}: {
  w: number;
  d: number;
  h: number;
  keyDef: KeycapKey;
  m: Material;
  unit: number;
  fontFamily: string;
}) {
  const side = unit * 0.13;
  const front = unit * 0.17;
  const back = unit * 0.08;
  const r0 = unit * 0.1;
  const r1 = unit * 0.085;
  const slices: React.ReactNode[] = [];
  for (let k = 0; k < SLICES; k++) {
    const tt = k / (SLICES - 1);
    const p = profile(tt);
    const base = mix(m.sideBottom, m.sideTop, Math.min(1, tt * 1.15));
    const rim = Math.max(0, (tt - 0.7) / 0.3);
    slices.push(
      <div
        key={k}
        style={{
          position: "absolute",
          left: side * p,
          right: side * p,
          top: back * p,
          bottom: front * p,
          borderRadius: r0 + (r1 - r0) * tt,
          transform: `translateZ(${tt * h}px)`,
          background: [
            `linear-gradient(180deg, rgba(255,255,255,${m.rim * rim * 0.5}) 0%, transparent 40%, rgba(0,0,0,${m.front * (1 - rim * 0.5)}) 100%)`,
            `linear-gradient(90deg, rgba(255,255,255,${m.left + rim * m.rim * 0.25}) 0%, transparent 30%, transparent 62%, rgba(0,0,0,${m.right}) 100%)`,
            rgb(base),
          ].join(", "),
        }}
      />,
    );
  }
  const topInset = profile(1);
  const legendSize = unit * (keyDef.label.length > 1 ? 0.2 : 0.36);
  return (
    <div
      style={{
        position: "absolute",
        left: -w / 2,
        top: -d / 2,
        width: w,
        height: d,
        transformStyle: "preserve-3d",
      }}
    >
      {slices}
      <div
        style={{
          position: "absolute",
          left: side * topInset,
          right: side * topInset,
          top: back * topInset,
          bottom: front * topInset,
          borderRadius: r1,
          transform: `translateZ(${h + 0.5}px)`,
          background: [
            `radial-gradient(ellipse 72% 64% at 50% 54%, rgba(0,0,0,${m.dish * 0.5}) 0%, rgba(0,0,0,${m.dish * 0.18}) 55%, transparent 100%)`,
            `linear-gradient(160deg, rgba(255,255,255,${m.sheen}) 0%, transparent 45%)`,
            rgb(m.top),
          ].join(", "),
          boxShadow: `inset 0 ${unit * 0.012}px 0 rgba(255,255,255,${m.rim * 0.5}), inset 0 -${unit * 0.02}px ${unit * 0.03}px rgba(0,0,0,${m.dish * 0.5})`,
        }}
      >
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontFamily,
            fontWeight: 400,
            fontSize: legendSize,
            lineHeight: 1,
            letterSpacing: "-0.02em",
            color: m.legend,
            paddingBottom: keyDef.sub ? unit * 0.06 : 0,
          }}
        >
          {SYMBOLS[keyDef.label] ? (
            <svg
              width={legendSize * 0.86}
              height={legendSize * 0.86}
              viewBox="0 0 24 24"
              fill="none"
              stroke={m.legend}
              strokeWidth={1.7}
              strokeLinecap="round"
              strokeLinejoin="round"
              aria-hidden
            >
              <path d={SYMBOLS[keyDef.label]} />
            </svg>
          ) : (
            keyDef.label
          )}
        </div>
        {keyDef.sub ? (
          <div
            style={{
              position: "absolute",
              left: unit * 0.09,
              bottom: unit * 0.07,
              fontFamily,
              fontWeight: 400,
              fontSize: unit * 0.085,
              letterSpacing: "0.01em",
              color: m.sub,
            }}
          >
            {keyDef.sub}
          </div>
        ) : null}
      </div>
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function KeycapPress(props: KeycapPressProps) {
  const {
    keys = DEFAULT_KEYS,
    label = DEFAULT_LABEL,
    material = "dark",
    theme,
    accent = "#3B5BFD",
    ground,
    groundParams,
    glow: glowK = 1,
    ink,
    background,
    fontFamily = sans,
    scale = 1,
    delay = 0,
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width, height, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    keycapPressTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const cameraEl = tl.get("camera");
  const glowEl = tl.get("glow");
  const chordEl = tl.get("chord");
  const liftEl = tl.get("lift");
  const tall = height > width;
  const u = tall ? width / 760 : Math.min(width / 1280, height / 720);
  const m = MATERIALS[material];
  const look = theme ?? material;
  const stage = STAGES[look];
  const resolvedGround: GshPresetId | undefined =
    ground ??
    (groundParams ? undefined : look === "dark" ? "spotlight" : "glasswork");
  const acc = hexToRgb(accent);

  const defs = keyDefs(keys);
  const unit = 205 * u * (tall ? 1.22 : 1) * (defs.length > 2 ? 0.82 : 1);
  const gap = unit * 0.1;
  const widths = defs.map((k) => (k.width ?? 1) * unit);
  const total = widths.reduce((s, x) => s + x, 0) + gap * (defs.length - 1);
  const centers: number[] = [];
  let cursor = -total / 2;
  for (const w of widths) {
    centers.push(cursor + w / 2);
    cursor += w + gap;
  }
  const depth = unit;
  const capH = unit * 0.44;
  const travel = unit * 0.13;
  const presses = defs.map((_, i) => tl.get(`press:${i}`));
  const pressAt = presses.map((e) => e.start);
  const chord = chordEl.start;
  const releaseAt = presses.map((e) => e.end);
  const settle = spring({
    frame: t - cameraEl.start,
    fps,
    config: HEAVY,
    durationInFrames: cameraEl.length,
  });
  const lift = interpolate(t, [liftEl.start, liftEl.end], [0, 1], {
    ...CLAMP,
    easing: CAMERA,
  });
  const rotX = 50 - settle * 8 - lift * 3;
  const rotZ = interpolate(
    t,
    [cameraEl.start, cameraEl.start + cameraEl.beat("drift")],
    [-9, -4],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const camScale = 1.04 - settle * 0.04 - lift * 0.06;
  const kick = interpolate(
    t,
    [chord, chord + chordEl.beat("kick"), chord + chordEl.beat("kickEnd")],
    [0, 1, 0],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  const keysY0 = height * (tall ? 0.42 : 0.46);
  const keysDy = height * -(lift * (tall ? 0.05 : 0.08)) + kick * 2 * u;
  const keysY = keysY0 + keysDy;
  const perspective = 1800 * u;

  const keyState = defs.map((_, i) => {
    const rise = spring({
      frame: t - tl.get(`key:${i}`).start,
      fps,
      config: CARD,
    });
    const down = Math.min(
      1.06,
      spring({
        frame: t - pressAt[i],
        fps,
        config: { mass: 0.4, damping: 14, stiffness: 320 },
      }),
    );
    const up = spring({
      frame: t - releaseAt[i],
      fps,
      config: CHIP,
    });
    const press = down * (1 - up);
    return { rise, press };
  });

  const camera = (children: React.ReactNode) => (
    <AbsoluteFill
      style={{
        perspective,
        perspectiveOrigin: `50% ${(keysY / height) * 100}%`,
      }}
    >
      <div
        style={{
          position: "absolute",
          left: width / 2,
          // Laid out where the keys start; the lift after the chord is a
          // transform, since layout rounds a box edge to a whole pixel and
          // every cap would step up with it.
          top: keysY0,
          width: 0,
          height: 0,
          transformStyle: "preserve-3d",
          transform: `${keysDy === 0 ? "" : `translateY(${keysDy}px) `}scale(${camScale}) rotateX(${rotX}deg) rotateZ(${rotZ}deg)`,
        }}
      >
        {children}
      </div>
    </AbsoluteFill>
  );
  const ripples: React.ReactNode[] = [];
  defs.forEach((_, i) => {
    const age = t - pressAt[i];
    const ripple = presses[i].beat("ripple");
    if (age < 0 || age > ripple) return;
    const p = interpolate(age, [0, ripple], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
    const size = widths[i] * (1.05 + p * 1.5);
    const sizeY = depth * (1.05 + p * 1.5);
    ripples.push(
      <div
        key={`r${i}`}
        style={{
          position: "absolute",
          left: centers[i] - size / 2,
          top: -sizeY / 2 + depth * 0.04,
          width: size,
          height: sizeY,
          borderRadius: unit * (0.2 + p * 0.5),
          border: `${unit * 0.035}px solid rgba(${stage.ripple},${(1 - p) * 0.12})`,
          boxShadow: `0 0 ${unit * 0.1}px rgba(${acc},${(1 - p) * 0.22})`,
          filter: `blur(${unit * (0.012 + p * 0.03)}px)`,
        }}
      />,
    );
  });
  const chordAge = t - chord;
  if (chordAge >= 0 && chordAge < chordEl.length) {
    for (const [lag, strength] of [
      [0, 1],
      [chordEl.beat("echo"), 0.55],
    ] as const) {
      const a = chordAge - lag;
      if (a < 0) continue;
      const p = interpolate(a, [0, chordEl.beat("ring")], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
      const sx = total * (1.1 + p * 1.6);
      const sy = depth * (1.1 + p * 2.6);
      ripples.push(
        <div
          key={`c${lag}`}
          style={{
            position: "absolute",
            left: -sx / 2,
            top: -sy / 2 + depth * 0.05,
            width: sx,
            height: sy,
            borderRadius: "50%",
            border: `${unit * 0.04}px solid rgba(${stage.ripple},${(1 - p) * 0.1 * strength})`,
            boxShadow: `0 0 ${unit * 0.14}px rgba(${acc},${(1 - p) * 0.22 * strength}), inset 0 0 ${unit * 0.14}px rgba(${acc},${(1 - p) * 0.14 * strength})`,
            filter: `blur(${unit * (0.015 + p * 0.035)}px)`,
          }}
        />,
      );
    }
  }
  const poolFlash = interpolate(
    chordAge,
    [0, chordEl.beat("flash"), chordEl.beat("flashEnd")],
    [0, 1, 0],
    CLAMP,
  );
  const glowRest = interpolate(t, [glowEl.start, glowEl.end], [0, 0.35], {
    ...CLAMP,
    easing: EASE_IO,
  });
  const glowHold = interpolate(
    chordAge,
    [0, chordEl.beat("glow"), chordEl.beat("glowEnd")],
    [0, 1, 0.7],
    {
      ...CLAMP,
      easing: EASE_OUT,
    },
  );
  const glow = Math.max(glowRest, glowHold);
  const glowSpread =
    1 +
    0.12 *
      interpolate(chordAge, [0, chordEl.beat("glowEnd")], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
  const gx = 50 + Math.sin(t / 47) * 1.5;
  const underglow = `radial-gradient(closest-side at ${gx}% 50%, rgba(${acc},${stage.glowA}) 0%, rgba(${acc},${stage.glowA * 0.45}) 55%, transparent 100%)`;

  const floor = camera(
    <>
      <div
        style={{
          position: "absolute",
          left: -total,
          top: -depth * 1.4,
          width: total * 2,
          height: depth * 2.8,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, rgba(${acc},${0.16 * poolFlash}), transparent)`,
        }}
      />
      <div
        style={{
          position: "absolute",
          left: -total * 0.95 * glowSpread,
          top: -depth * 1.1 * glowSpread + depth * 0.05,
          width: total * 1.9 * glowSpread,
          height: depth * 2.2 * glowSpread,
          background: underglow,
          opacity: glow * glowK,
          mixBlendMode: stage.glowBlend,
          filter: `blur(${unit * 0.12}px)`,
        }}
      />
      {ripples}
      {defs.map((_, i) => {
        const { rise, press } = keyState[i];
        const w = widths[i];
        const tight = press;
        const spread = (1 - tight) * 0.5 + 0.5;
        return (
          <div key={`s${i}`}>
            <div
              style={{
                position: "absolute",
                left: centers[i] - w * 0.55 + unit * 0.04,
                top: -depth * 0.5 + depth * 0.14,
                width: w * 1.1,
                height: depth * 1.1,
                borderRadius: unit * 0.24,
                background: m.shadow,
                opacity: 0.55 * rise * (0.85 + tight * 0.15),
                filter: `blur(${unit * (0.16 + spread * 0.12)}px)`,
              }}
            />
            <div
              style={{
                position: "absolute",
                left: centers[i] - w * 0.48,
                top: -depth * 0.48 + depth * 0.03,
                width: w * 0.96,
                height: depth * 0.96,
                borderRadius: unit * 0.12,
                background: m.shadow,
                opacity: (0.6 + tight * 0.3) * rise,
                filter: `blur(${unit * (0.045 + (1 - tight) * 0.04)}px)`,
              }}
            />
          </div>
        );
      })}
    </>,
  );

  const caps = camera(
    defs.map((k, i) => {
      const { rise, press } = keyState[i];
      const off = 1 - rise;
      const z = unit * 0.035 - press * travel - off * unit * 0.6;
      const y = off * unit * 2.6;
      const tilt = off * -24;
      return (
        <div
          key={i}
          style={{
            position: "absolute",
            left: centers[i],
            top: 0,
            width: 0,
            height: 0,
            transformStyle: "preserve-3d",
            transform: `translate3d(0, ${y}px, ${z}px) rotateX(${tilt}deg)`,
          }}
        >
          <Keycap
            w={widths[i] - unit * 0.02}
            d={depth}
            h={capH}
            keyDef={k}
            m={m}
            unit={unit}
            fontFamily={fontFamily}
          />
        </div>
      );
    }),
  );
  const words = label.split(" ");
  const word = (i: number) => {
    const e = tl.get(`word:${i}`);
    return interpolate(t, [e.start, e.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };

  return (
    <AbsoluteFill
      style={{
        background:
          background === undefined
            ? stage.base
            : background === "transparent"
              ? undefined
              : background,
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          <GshGround
            preset={resolvedGround}
            params={
              groundParams ?? (look === "light" ? LIGHT_GLASS : undefined)
            }
            timeOffset={look === "dark" ? 2 : 5}
            timeScale={0.45}
          />
          <AbsoluteFill
            style={{
              background: `radial-gradient(60% 55% at 50% ${tall ? 42 : 46}%, rgba(${stage.scrim},${stage.scrimA}) 0%, rgba(${stage.scrim},${stage.scrimA * 0.4}) 100%)`,
            }}
          />
        </>
      ) : null}
      <ScaleLayer scale={scale}>
        {floor}
        {caps}
        <div
          style={{
            position: "absolute",
            left: "10%",
            right: "10%",
            top: height * (tall ? 0.6 : 0.7),
            textAlign: "center",
            fontFamily,
            fontWeight: 300,
            fontSize: (tall ? 72 : 60) * u,
            lineHeight: 1.08,
            letterSpacing: "-0.04em",
            color: ink ?? stage.fg,
            textWrap: "balance",
          }}
        >
          {words.map((w, i) => (
            <span
              key={i}
              style={{
                display: "inline-block",
                whiteSpace: "pre",
                opacity: word(i),
                transform: `translateY(${(1 - word(i)) * 14 * u}px)${glide(midway(word(i)))}`,
                filter: `blur(${(1 - word(i)) * 5 * u}px)`,
              }}
            >
              {i < words.length - 1 ? `${w} ` : w}
            </span>
          ))}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The keys rise in while the camera settles and the underglow warms up; the
// keys are pressed one after another, the last press is the chord that
// kicks, flashes and lifts the camera, the label writes in word by word and
// the keys come back up in reverse. Frames on the 30 fps scene timeline,
// after `delay` and `speed`. The ids are public: a saved `timing` prop refers
// to them.

export type KeycapPressElementId =
  | `key:${number}`
  | "camera"
  | "glow"
  | `press:${number}`
  | "chord"
  | "lift"
  | `word:${number}`;

export interface KeycapKey {
  label: string;
  sub?: string;
  width?: number;
}

export interface KeycapPressTimingProps {
  keys?: (string | KeycapKey)[];
  label?: string;
  stagger?: number;
}

export const DEFAULT_KEYS: KeycapKey[] = [
  { label: "⌘", sub: "command", width: 1.25 },
  { label: "K" },
];
export const DEFAULT_LABEL = "Everything, one shortcut away";
const STAGGER = 3;

/** The keys, each as a `KeycapKey`. */
export function keyDefs(keys: (string | KeycapKey)[]): KeycapKey[] {
  return keys.map((k) => (typeof k === "string" ? { label: k } : k));
}

// Each key rises in as a chain, the first before the first frame. The camera
// settles over its length and drifts its roll until `drift`. `press:<i>`
// holds key i down until its end, the release, with a ripple over `ripple`;
// presses are a chain. The chord, on the last press, kicks the keys between
// `kick` and `kickEnd`, flashes the pool to `flash` and back by `flashEnd`,
// lifts the glow to `glow` and holds it to `glowEnd`, and sends two rings out
// over `ring`, the second `echo` frames late. Words are a chain after it.
export const keycapPressTimeline = defineTimeline<
  KeycapPressElementId,
  KeycapPressTimingProps
>(({ keys = DEFAULT_KEYS, label = DEFAULT_LABEL, stagger = STAGGER }) => {
  const defs = keyDefs(keys);
  const n = defs.length;
  const pressGap = n > 2 ? 10 : 12;
  const pressAt = defs.map((_, i) => 36 + i * pressGap);
  const chord = pressAt[n - 1];
  const releaseAt = defs.map((_, i) => chord + 22 + (n - 1 - i) * 4);

  const elements: TimelineElement<KeycapPressElementId>[] = defs.map(
    (key, i) => ({
      id: `key:${i}` as const,
      lane: "Keys",
      label: key.label,
      start: -8 + i * 5,
      length: 5,
      follows: i > 0 ? (`key:${i - 1}` as const) : undefined,
    }),
  );
  elements.push(
    {
      id: "camera",
      lane: "Camera",
      label: "Camera settles",
      start: 0,
      length: 54,
      beats: { drift: 135 },
    },
    {
      id: "glow",
      lane: "Glow",
      label: "Underglow warms",
      start: 6,
      length: 34,
    },
  );
  defs.forEach((key, i) => {
    elements.push({
      id: `press:${i}`,
      lane: "Presses",
      label: `Press ${key.label}`,
      start: pressAt[i],
      length: releaseAt[i] - pressAt[i],
      follows: i > 0 ? `press:${i - 1}` : undefined,
      beats: { ripple: 34 },
    });
  });
  elements.push(
    {
      id: "chord",
      lane: "Glow",
      label: "Chord",
      start: chord,
      length: 50,
      follows: `press:${n - 1}`,
      beats: {
        kick: 3,
        kickEnd: 14,
        flash: 3,
        flashEnd: 30,
        glow: 4,
        glowEnd: 40,
        echo: 7,
        ring: 44,
      },
    },
    {
      id: "lift",
      lane: "Camera",
      label: "Camera lifts",
      start: chord + 2,
      length: 32,
      follows: "chord",
    },
  );
  label.split(" ").forEach((word, i) => {
    elements.push({
      id: `word:${i}`,
      lane: "Label",
      label: word,
      start: chord + 6 + i * stagger,
      length: 20,
      follows: i > 0 ? `word:${i - 1}` : "chord",
    });
  });
  return elements.sort((a, b) => a.start - b.start);
});
